ei.item_type = 'PLACE' AND ei.approval_status = 'APPROVED' AND ei.visibility_status = 'VISIBLE' AND ei.deleted_at IS NULL AND p.deleted_at IS NULL AND p.is_active = TRUE
AND IN
#{placeKind}
AND p.region1 IN #{value}
AND ( p.region2 IN #{value} OR p.region2 IS NULL OR TRIM(p.region2) = ''
OR p.region2 NOT IN #{knownRegion2}
)
AND ( p.region2 IS NULL OR TRIM(p.region2) = ''
OR p.region2 NOT IN #{knownRegion2}
)
AND 1 = 0
AND p.region2 IN #{value}
AND p.region3 IN #{value}
AND ( NULLIF(TRIM(pt.name), '') LIKE CONCAT('%', #{request.keyword}, '%') OR p.name LIKE CONCAT('%', #{request.keyword}, '%') OR NULLIF(TRIM(pt.brand), '') LIKE CONCAT('%', #{request.keyword}, '%') OR p.brand LIKE CONCAT('%', #{request.keyword}, '%') OR NULLIF(TRIM(pt.branch), '') LIKE CONCAT('%', #{request.keyword}, '%') OR p.branch LIKE CONCAT('%', #{request.keyword}, '%') OR NULLIF(TRIM(pt.address_display), '') LIKE CONCAT('%', #{request.keyword}, '%') OR p.address_road LIKE CONCAT('%', #{request.keyword}, '%') OR NULLIF(TRIM(pt.address_detail), '') LIKE CONCAT('%', #{request.keyword}, '%') OR p.address_detail LIKE CONCAT('%', #{request.keyword}, '%') )
AND p.has_foreign_lang = TRUE AND p.has_parking = TRUE AND p.reservable = TRUE AND p.takeout_available = TRUE AND p.card_payment_available = TRUE AND p.smoke_free = TRUE AND p.kid_facility = TRUE AND p.has_restroom = TRUE
AND (
EXISTS ( SELECT 1 FROM place_activity filter_pa JOIN activity filter_a ON filter_a.activity_id = filter_pa.activity_id WHERE filter_pa.place_id = p.place_id AND filter_pa.deleted_at IS NULL AND filter_a.deleted_at IS NULL AND filter_a.sector_id IN #{sectorId} )
OR EXISTS ( SELECT 1 FROM place_activity filter_pa WHERE filter_pa.place_id = p.place_id AND filter_pa.deleted_at IS NULL AND filter_pa.activity_id IN #{activityId} )
)
AND EXISTS ( SELECT 1 FROM explore_item_likes saved_like WHERE saved_like.item_id = ei.item_id AND saved_like.member_id = #{memberId} AND saved_like.deleted_at IS NULL )

